import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledFieldContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '8px',
});

export const StyledFieldLabel = styled.label({
  fontSize: '14px',
  fontWeight: '600',
  fontFamily: theme.fonts.paragraph,
});
